class Table:
    def __init__(self):
        self.chains = [[] for _ in range(8)]
        self.count = 0
    @property
    def capacity(self):
        return len(self.chains)
    def __len__(self):
        return self.count
    def find(self, key):
        chain = self.chains[hash(key) % self.capacity]
        for index, entry in enumerate(chain):
            if entry[0] is key or entry[0] == key:
                return chain, index
        return chain, None
    def __getitem__(self, key):
        chain, index = self.find(key)
        if index is None:
            raise KeyError(key)
        return chain[index][1]
    def __setitem__(self, key, value):
        chain, index = self.find(key)
        if index is not None:
            chain[index][1] = value
            return
        chain.append([key, value])
        self.count += 1
        if 4*self.count > 3*self.capacity:
            old = self.chains
            self.chains = [[] for _ in range(self.capacity*2)]
            for entries in old:
                for entry in entries:
                    self.chains[hash(entry[0]) % self.capacity].append(entry)
    def __delitem__(self, key):
        chain, index = self.find(key)
        if index is None:
            raise KeyError(key)
        del chain[index]
        self.count -= 1

