import json
import multiprocessing
import os
import pathlib
import sys
import tempfile

def write_records(jobs, directory):
    # Inline computation; no numeric Python function return or MP queue result.
    for index, value in jobs:
        if value < 0:
            row = {'ok': False, 'error': 'negative'}
        else:
            row = {'ok': True, 'value': value*value, 'pid': os.getpid()}
        with open(pathlib.Path(directory)/(str(index)+'.json'), 'w', encoding='utf-8') as stream:
            json.dump(row, stream)

def run(values):
    if not values:
        return []
    context = multiprocessing.get_context('spawn')
    children = []
    with tempfile.TemporaryDirectory(prefix='owned-file-results-', dir=pathlib.Path.cwd()) as directory:
        try:
            count = min(2, len(values))
            for slot in range(count):
                jobs = [(index, values[index]) for index in range(slot, len(values), count)]
                child = context.Process(target=write_records, args=(jobs, directory))
                child.start()
                children.append(child)
            for child in children:
                child.join(timeout=5)
                if child.exitcode != 0:
                    raise RuntimeError('worker failed')
            return [json.loads((pathlib.Path(directory)/(str(index)+'.json')).read_text())
                    for index in range(len(values))]
        finally:
            for child in children:
                if child.is_alive():
                    child.terminate()
                child.join(timeout=2)

def main():
    values = json.loads(pathlib.Path(sys.argv[1]).read_text())
    pathlib.Path(sys.argv[2]).write_text(json.dumps(run(values)), encoding='utf-8')

if __name__ == '__main__':
